from copy import deepcopy


_HEADER = "Service | Destination | Platform | Departure"


def _snapshot(records, destinations):
    if isinstance(records, (str, bytes)):
        raise TypeError("records must be iterable")
    if not isinstance(destinations, Mapping):
        raise TypeError("destinations must be a mapping")
    destination_copy = deepcopy(dict(destinations))
    for code, name in destination_copy.items():
        if not isinstance(code, str) or not isinstance(name, str):
            raise TypeError("destination codes and names must be strings")
        if not code or not name:
            raise ValueError("destination codes and names must not be empty")
    try:
        rows = deepcopy(list(records))
    except TypeError as exc:
        raise TypeError("records must be iterable") from exc
    required = ("carrier", "number", "destination", "platform", "departure")
    for row in rows:
        if not isinstance(row, Mapping):
            raise TypeError("each record must be a mapping")
        if any(field not in row for field in required):
            raise ValueError("record is missing a required field")
        for field in ("carrier", "destination", "platform"):
            if not isinstance(row[field], str):
                raise TypeError(f"{field} must be a string")
            if not row[field]:
                raise ValueError(f"{field} must not be empty")
        if isinstance(row["number"], bool) or not isinstance(row["number"], int):
            raise TypeError("number must be an integer")
        if row["number"] < 0:
            raise ValueError("number must be non-negative")
        if isinstance(row["departure"], bool) or not isinstance(row["departure"], int):
            raise TypeError("departure must be an integer")
        if not 0 <= row["departure"] <= 1439:
            raise ValueError("departure is outside the day")
    return rows, destination_copy


def _render(rows, destinations):
    lines = [_HEADER]
    for row in rows:
        code = row["destination"]
        destination = destinations.get(code, f"Unknown ({code})")
        hour, minute = divmod(row["departure"], 60)
        lines.append(
            f'{row["carrier"]}{row["number"]} | {destination} | '
            f'{row["platform"]} | {hour:02d}:{minute:02d}'
        )
    return "\n".join(lines)


def render_by_service(records, destinations):
    rows, names = _snapshot(records, destinations)
    rows.sort(key=lambda row: (row["carrier"], row["number"]))
    return _render(rows, names)


