import copy
import unittest

from solution import render_by_departure, render_by_service


HEADER = "Service | Destination | Platform | Departure"


class RenderingTests(unittest.TestCase):
    def setUp(self):
        self.destinations = {"BLR": "Bengaluru", "DEL": "New Delhi"}
        self.records = [
            {"carrier": "ZX", "number": 20, "destination": "DEL", "platform": "4", "departure": 65},
            {"carrier": "AA", "number": 9, "destination": "BLR", "platform": "1", "departure": 600},
            {"carrier": "AA", "number": 2, "destination": "XXX", "platform": "2", "departure": 65, "ignored": []},
        ]

    def test_render_by_service(self):
        self.assertEqual(
            render_by_service(self.records, self.destinations),
            HEADER + "\nAA2 | Unknown (XXX) | 2 | 01:05\nAA9 | Bengaluru | 1 | 10:00\nZX20 | New Delhi | 4 | 01:05",
        )

    def test_render_by_departure_and_stability(self):
        records = [
            {"carrier": "A", "number": 1, "destination": "X", "platform": "first", "departure": 0},
            {"carrier": "A", "number": 1, "destination": "Y", "platform": "second", "departure": 0},
            {"carrier": "A", "number": 0, "destination": "X", "platform": "last-key", "departure": 1439},
        ]
        self.assertEqual(
            render_by_departure(records, {}),
            HEADER + "\nA1 | Unknown (X) | first | 00:00\nA1 | Unknown (Y) | second | 00:00\nA0 | Unknown (X) | last-key | 23:59",
        )

    def test_empty_records(self):
        self.assertEqual(render_by_service([], {}), HEADER)
        self.assertEqual(render_by_departure([], {}), HEADER)

    def test_inputs_are_unchanged(self):
        records_before = copy.deepcopy(self.records)
        destinations_before = copy.deepcopy(self.destinations)
        render_by_service(self.records, self.destinations)
        render_by_departure(self.records, self.destinations)
        self.assertEqual(self.records, records_before)
        self.assertEqual(self.destinations, destinations_before)

    def test_missing_fields_are_value_errors(self):
        base = {"carrier": "A", "number": 1, "destination": "BLR", "platform": "1", "departure": 0}
        for field in base:
            malformed = dict(base)
            del malformed[field]
            with self.subTest(field=field):
                with self.assertRaises(ValueError):
                    render_by_service([malformed], self.destinations)

    def test_record_type_and_scalar_type_errors(self):
        with self.assertRaises(TypeError):
            render_by_service([[]], self.destinations)
        cases = [
            ("carrier", 1), ("destination", None), ("platform", []),
            ("number", True), ("number", 1.0), ("departure", False), ("departure", "0"),
        ]
        base = {"carrier": "A", "number": 1, "destination": "BLR", "platform": "1", "departure": 0}
        for field, value in cases:
            row = dict(base)
            row[field] = value
            with self.subTest(field=field, value=value):
                with self.assertRaises(TypeError):
                    render_by_departure([row], self.destinations)

    def test_invalid_values(self):
        base = {"carrier": "A", "number": 1, "destination": "BLR", "platform": "1", "departure": 0}
        for field, value in [("carrier", ""), ("destination", ""), ("platform", ""), ("number", -1), ("departure", -1), ("departure", 1440)]:
            row = dict(base)
            row[field] = value
            with self.subTest(field=field, value=value):
                with self.assertRaises(ValueError):
                    render_by_service([row], self.destinations)

    def test_invalid_destination_mapping(self):
        with self.assertRaises(TypeError):
            render_by_service([], [])
        for mapping in [{1: "name"}, {"": "name"}, {"X": 2}]:
            with self.subTest(mapping=mapping):
                expected = TypeError if mapping == {"X": 2} or mapping == {1: "name"} else ValueError
                with self.assertRaises(expected):
                    render_by_service([], mapping)
        with self.assertRaises(ValueError):
            render_by_service([], {"X": ""})


if __name__ == "__main__":
    unittest.main()

